def save(path, text):
    temp_path = path + ".tmp"
    with open(temp_path, "w", encoding="utf-8") as f:
        f.write(text)
    os.fsync(f.fileno())
    try:
        os.replace(temp_path, path)
    except OSError:
        os.remove(temp_path)
        raise

